sys_script_include.script:
var ServiceCatalogMarkdownGenerator = (function() {
    /** @type {ServiceCatalogMarkdownGeneratorConstructor} */
    ServiceCatalogMarkdownGeneratorConstructor = Class.create();

    /**
     * @param {(GlideRecord | GlideRecordSecure)} varGr - item_option_new
     * @param {string[]} markdownLines
     * @param {MarkdownGenerationContext} context
     * @param {string} [tableUrl]
     */
    function pushVariableDetailMarkdown(varGr, markdownLines, context) {
        markdownLines.push('');
        markdownLines.push("### Variable: " + varGr.getValue('name'));
        markdownLines.push('');

        if (varGr.getDisplayValue('map_to_field') == 'true') {
            markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(varGr.map_to_field.getLabel()) + ':** True');
            markdownLines.push(context.getColumnReferenceMdLink(varGr.record_producer_table, varGr.field));
        }

        /** @type {MultiLineItem[]} */
        var multiLineStack = [];
        context.pushDisplayValueListItem(varGr.type, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varGr.question_text, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varGr.conversational_label, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varGr.tooltip, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varGr.order, markdownLines, multiLineStack);
        context.pushListItemIfTrue(varGr.show_help, markdownLines);
        if (varGr.getDisplayValue('show_help') == 'true') {
            markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(varGr.show_help.getLabel()) + ':** True');
            context.pushDisplayValueListItem(varGr.help_tag, markdownLines, multiLineStack);
            context.pushDisplayValueListItem(varGr.help_text, markdownLines, multiLineStack);
            context.pushCodeListItem(varGr.instructions, 'html', markdownLines, multiLineStack);
        }
        var listChoices = false;
        var type = parseInt(varGr.getValue('type'));
        switch (type) {
            case 1: // Yes / No
                context.pushListItemIfTrue(varGr.include_none, markdownLines);
                break;
            case 2: // Multi Line Text
                context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                break;
            case 3: // Multiple Choice
                context.pushDisplayValueListItem(varGr.choice_direction, markdownLines, multiLineStack);
                context.pushListItemIfTrue(varGr.include_none, markdownLines);
                context.pushListItemIfTrue(varGr.do_not_select_first, markdownLines);
                context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                listChoices = true;
                break;
            case 5: // Select Box
            case 18: // Lookup Select Box
                if (!gs.nil(varGr.choice_table)) {
                    context.pushTableReferenceListItem(varGr.choice_table, markdownLines);
                    context.pushFieldReferenceListItem(varGr.choice_table, varGr.choice_field, markdownLines);
                }
                context.pushListItemIfTrue(varGr.include_none, markdownLines);
                context.pushListItemIfTrue(varGr.lookup_unique, markdownLines);
                context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                listChoices = true;
                break;
            case 8: // Reference
                context.pushTableReferenceListItem(varGr.reference, markdownLines);
                context.pushDisplayValueListItem(varGr.use_reference_qualifier, markdownLines, multiLineStack);
                switch (varGr.getValue('use_reference_qualifier')) {
                    case 'simple':
                        context.pushCodeListItem(varGr.reference_qual_condition, 'text', markdownLines, multiLineStack);
                        break;
                    default:
                        context.pushCodeListItem(varGr.reference_qual, 'text', markdownLines, multiLineStack);
                        break;
                }
                context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                break;
            case 19: // Container Start
                context.pushListItemIfTrue(varGr.display_title, markdownLines);
                context.pushDisplayValueListItem(varGr.layout, markdownLines, multiLineStack);
                break;
            case 22: // Lookup Multiple Choice
                context.pushDisplayValueListItem(varGr.lookup_source, markdownLines, multiLineStack);
                switch (varGr.getValue('lookup_source')) {
                    case 'choice':
                        if (!gs.nil(varGr.choice_table)) {
                            context.pushTableReferenceListItem(varGr.choice_table, markdownLines);
                            context.pushFieldReferenceListItem(varGr.choice_table, varGr.choice_field, markdownLines);
                        }
                        break;
                }
                context.pushListItemIfTrue(varGr.choice_direction, markdownLines);
                context.pushListItemIfTrue(varGr.include_none, markdownLines);
                context.pushListItemIfTrue(varGr.lookup_unique, markdownLines);
                context.pushValueListItem(varGr.reference_qual, markdownLines, multiLineStack);
                context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                break;
            case 4: // Numeric Scale
            case 6: // Single Line Text
            case 7: // CheckBox
            case 9: // Date
            case 10: // Date/Time
            case 11: // Label
            case 12: // Break
            case 14: // Custom
            case 15: // UI Page
            case 16: // Wide Single Line Text
            case 17: // Custom with Label
            case 20: // Container End
            case 21: // List Collector
            case 23: // HTML
            case 24: // Container Split
            case 25: // Masked
            case 26: // Email
            case 27: // URL
            case 28: // IP Address
            case 29: // Duration
            case 31: // Requested For
            case 32: // Rich Text Label
            case 33: // Attachment
            case 40: // Table Name
                break;
            default:
                markdownLines.push("- **Unknown type:** *" + varGr.getValue('type') + '*');
                break;
        }

        context.pushListItemIfTrue(varGr.global, markdownLines);
        context.pushListItemIfTrue(varGr.disable_initial_slot_fill, markdownLines);
        context.pushDisplayValueListItem(varGr.variable_width, markdownLines, multiLineStack);
        context.pushListItemIfFalse(varGr.visible_standalone, markdownLines);
        context.pushListItemIfFalse(varGr.visible_bundle, markdownLines);
        context.pushListItemIfTrue(varGr.not_available_conversation, markdownLines);
        context.pushListItemIfFalse(varGr.visible_guide, markdownLines);
        context.pushListItemIfFalse(varGr.visible_summary, markdownLines);
        switch (type) {
            case 20: // Container End
            case 24: // Container Split
            case 32: // Rich Text Label
                break;
            case 19: // Container Start
                context.pushListItemIfTrue(varGr.hidden, markdownLines);
                break;
            default:
                context.pushListItemIfTrue(varGr.mandatory, markdownLines);
                if (!varGr.mandatory) {
                    context.pushListItemIfTrue(varGr.hidden, markdownLines);
                    context.pushListItemIfTrue(varGr.read_only, markdownLines);
                }
                break;
        }
        switch (type) {
            case 23: // HTML
                if (gs.nil(glideRecord.default_html_value))
                    context.pushCodeListItem(varGr.default_value, 'text', markdownLines, multiLineStack, true);
                else
                    context.pushCodeListItem(varGr.default_html_value, 'html', markdownLines, multiLineStack, true);
                break;
            case 32: // Rich Text Label
                context.pushCodeListItem(varGr.rich_text, 'html', markdownLines, multiLineStack, true);
                break;
            case 19: // Container Start
            case 20: // Container End
            case 24: // Container Split
                break;
            default:
                context.pushDisplayValueListItem(varGr.default_value, markdownLines, multiLineStack);
                break;
        }

        context.pushDisplayValueListItem(varGr.example_text, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varGr.validate_regex, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varGr.roles_to_use_also_request_for, markdownLines, multiLineStack);
        context.pushMultiLineItems(multiLineStack, markdownLines);

        if (listChoices) {
            var choiceGr = new GlideRecord('question_choice');
            choiceGr.addQuery('question', varGr.sys_id);
            choiceGr.addQuery('inactive', false);
            choiceGr.orderBy('order');
            choiceGr.query();
            if (choiceGr.next()) {
                markdownLines.push('');
                markdownLines.push('**Choices:**');
                markdownLines.push('');
                markdownLines.push('| Label | Value | Sequence |');
                markdownLines.push('| ----- | ----- | -------- |');
                text = text + "\n\n**Choices:**\n\n| Label | Value | Sequence |\n| ----- | ----- | -------- |";
                do {
                    markdownLines.push("\n| " + MarkdownGenerationContext.escapeForMarkdown(choiceGr.getValue('text'), true) + " | " + MarkdownGenerationContext.escapeForMarkdown(choiceGr.getValue('value'), true) + " | " + choiceGr.getDisplayValue('order') + " |");
                } while (choiceGr.next());
            }
        }
    }

    /**
     * @param {(GlideRecord | GlideRecordSecure)} varSetGr - item_option_new_set
     * @param {number} order
     * @param {string[]} markdownLines
     * @param {MarkdownGenerationContext} context
     */
    function pushVariableSetDetailMarkdown(varSetGr, markdownLines, context) {

    }

    /**
     * @typedef QuestionItem
     * @property {string} sys_id
     * @property {number} typeValue
     * @property {string} typeLabel
     * @property {string} question_text
     * @property {string} name
     * @property {boolean} is_set
     * @property {({ display: string: value: number })} order
     */

    /** @typedef {(QuestionItem & { field: string })} RecordProducerQuestionItem */

    /**
     * @param {(GlideRecord | GlideRecordSecure)} catItemGr - sc_cat_item_producer
     * @param {MarkdownGenerationContext} context
     * @return {string}
     */
    function getRecordProducerMarkdown(catItemGr, context) {
        /** @type {string[]} */
        var markdownLines = ['# "' + MarkdownGenerationContext.escapeForMarkdown(catItemGr.getValue('name')) + '" Record Producer', ''];
        /** @type {MultiLineItem[]} */
        var multiLineStack = [];
        context.pushTableReferenceListItem(catItemGr.table_name, markdownLines);
        context.pushValueListItem(catItemGr.short_description, markdownLines, multiLineStack);
        context.pushCodeListItem(catItemGr.description, 'html', markdownLines, multiLineStack);
        context.pushValueListItem(catItemGr.meta, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(catItemGr.redirect_url, markdownLines, multiLineStack);
        context.pushCodeListItem(catItemGr.script, 'javascript', markdownLines, multiLineStack);
        context.pushImageListItem(catItemGr.icon, markdownLines);
        context.pushImageListItem(catItemGr.picture, markdownLines);
        context.pushDisplayValueListItem(catItemGr.sc_catalogs, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(catItemGr.category, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(catItemGr.view, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(catItemGr.roles, markdownLines, multiLineStack);
        context.pushListItemIfTrue(catItemGr.can_cancel, markdownLines);
        context.pushDisplayValueListItem(catItemGr.template, markdownLines, multiLineStack);
        context.pushListItemIfTrue(catItemGr.no_attachment_v2, markdownLines);
        context.pushListItemIfTrue(catItemGr.mandatory_attachment, markdownLines);
        context.pushListItemIfTrue(catItemGr.no_save_as_draft, markdownLines);
        context.pushMultiLineItems(multiLineStack, markdownLines);

        var cat_item_sys_id = catItemGr.getValue('sys_id');
        /** @type {RecordProducerQuestionItem[]} */
        var allVariables = [];
        var variableGr = new GlideRecord('item_option_new');
        variableGr.addQuery('cat_item', cat_item_sys_id);
        variableGr.orderBy('order');
        variableGr.orderBy('name');
        variableGr.addActiveQuery();
        variableGr.query();
        while (variableGr.next())
            allVariables.push({
                sys_id: variableGr.getValue('sys_id'),
                typeValue: parseInt(variableGr.getValue('type')),
                typeLabel: MarkdownGenerationContext.escapeForMarkdown(variableGr.getDisplayValue('type')),
                question_text: gs.nil(variableGr.question_text) ? '' : MarkdownGenerationContext.escapeForMarkdown(variableGr.getDisplayValue('question_text')),
                field: gs.nil(variableGr.field) ? '' : MarkdownGenerationContext.escapeForMarkdown(variableGr.getDisplayValue('field')),
                name: variableGr.getValue('name'),
                is_set: false,
                order: gs.nil(variableGr.order) ? {
                    display: '',
                    value: NaN
                } : {
                    display: variableGr.getDisplayValue('order'),
                    value: parseInt(variableGr.getValue('order'))
                }
            });
        var varSetGr = new GlideRecord('io_set_item');
        varSetGr.addQuery('cat_item', cat_item_sys_id);
        varSetGr.orderBy('order');
        varSetGr.orderBy('variable_set.internal_name');
        varSetGr.query();
        while (varSetGr.next())
            allVariables.push({
                sys_id: varSetGr.getValue('sys_id'),
                typeValue: NaN,
                typeLabel: 'Variable Set',
                question_text: MarkdownGenerationContext.escapeForMarkdown(varSetGr.getDisplayValue('variable_set')),
                field: '',
                name: varSetGr.getValue('internal_name'),
                is_set: true,
                order: gs.nil(varSetGr.order) ? {
                    display: '',
                    value: NaN
                } : {
                    display: varSetGr.getDisplayValue('order'),
                    value: parseInt(varSetGr.getValue('order'))
                }
            });
        if (allVariables.length > 0) {
            /** @type {RecordProducerQuestionItem} */
            var item;
            var i;
            if (allVariables.length > 1) {
                allVariables = allVariables.sort(function(a, b) {
                    if (isNaN(a.order.value)) {
                        if (!isNaN(b.order.value))
                            return -1;
                    } else {
                        if (isNaN(b.order.value))
                            return 1;
                        var d = a.order.value - b.order.value;
                        if (d != 0)
                            return d;
                    }
                    if (a.name < b.name)
                        return -1;
                    return (a.name > b.name) ? 1 : 0;
                });
                var containerName = '';
                for (i = 0; i < allVariables.length; i++) {
                    item = allVariables[i];
                    if (!item.is_set) {
                        switch (item.typeValue) {
                            case 19: // Container Start
                                if (!gs.nil(item.question_text))
                                    containerName = item.question_text;
                                break;
                            case 24: // Container Split
                                if (containerName != '')
                                    item.question_text = containerName;
                                break;
                            case 20: // Container End
                                if (containerName != '')
                                    item.question_text = containerName;
                                containerName = '';
                                break;
                        }
                    }
                }
            }
            markdownLines.push(
                '',
                '## Variables',
                '',
                '| Type | Question | Field | Order |',
                '| ---- | -------- | ----- | ----- |'
            );
            for (i = 0; i < allVariables.length; i++) {
                item = allVariables[i];
                var type = item.typeLabel;
                if (!item.is_set)
                    switch (item.typeValue) {
                        case 19: // Container Start
                        case 24: // Container Split
                        case 20: // Container End
                            type = '*\\(' + type + '\\)*';
                            break;
                    }
                markdownLines.push('| ' + type + ' | [' + (item.question_text ? item.question_text : item.name) + (item.is_set ? '](#variable-set-' : '](#variable-') + item.name + ') | ' + item.field + ' | ' + item.order.display + ' |');
            }
            for (i = 0; i < allVariables.length; i++) {
                item = allVariables[i];
                if (item.is_set) {
                    varSetGr = new GlideRecord('io_set_item');
                    varSetGr.get(allVariables[i].sys_id);
                    pushVariableSetDetailMarkdown(varSetGr, markdownLines, context);
                } else {
                    variableGr = new GlideRecord('item_option_new');
                    variableGr.get(allVariables[i].sys_id);
                    pushVariableDetailMarkdown(variableGr, markdownLines, context);
                }
            }
        }

        return markdownLines.join("\n") + "\n";
    }

    ServiceCatalogMarkdownGeneratorConstructor.getRecordProducerMarkdown = getRecordProducerMarkdown;

    /**
     * @param {(GlideRecord | GlideRecordSecure)} catItemGr - sc_cat_item
     * @param {MarkdownGenerationContext} context
     * @return {string}
     */
    function getCatalogItemMarkdown(catItemGr, context) {
        switch (catItemGr.getValue('sys_class_name')) {
            case 'sc_cat_item_producer':
                var rpGr = new GlideRecord('sc_cat_item_producer');
                rpGr.get(sys_id);
                return getRecordProducerMarkdown(catItemGr, context);
        }
        /** @type {string[]} */
        var markdownLines = ['# "' + MarkdownGenerationContext.escapeForMarkdown(catItemGr.getValue('name')) + '" Catalog Item', ''];
        /** @type {MultiLineItem[]} */
        var multiLineStack = [];
        context.pushDisplayValueListItem(catItemGr.sc_catalogs, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(catItemGr.category, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(catItemGr.roles, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(catItemGr.fulfillment_automation_level, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(catItemGr.group, markdownLines);
        context.pushDisplayValueListItem(catItemGr.order, markdownLines, multiLineStack);
        context.pushValueListItem(catItemGr.short_description, markdownLines, multiLineStack);
        context.pushCodeListItem(catItemGr.description, 'html', markdownLines, multiLineStack);
        context.pushValueListItem(catItemGr.meta, markdownLines, multiLineStack);
        if (gs.nil(catItemGr.flow_designer_flow))
            context.pushDisplayValueListItem(gs.nil(catItemGr.workflow) ? catItemGr.workflow : catItemGr.delivery_plan, markdownLines, multiLineStack);
        else
            context.pushFlowReferenceListItem(catItemGr.flow_designer_flow, markdownLines);
        context.pushImageListItem(catItemGr.icon, markdownLines);
        context.pushImageListItem(catItemGr.picture, markdownLines);
        context.pushDisplayValueListItem(catItemGr.request_method, markdownLines, multiLineStack);
        context.pushListItemIfTrue(catItemGr.no_cart_v2, markdownLines);
        context.pushListItemIfTrue(catItemGr.no_quantity_v2, markdownLines);
        context.pushListItemIfTrue(catItemGr.no_delivery_time_v2, markdownLines);
        context.pushListItemIfTrue(catItemGr.no_save_as_draft, markdownLines);
        context.pushListItemIfTrue(catItemGr.no_attachment_v2, markdownLines);
        context.pushListItemIfTrue(catItemGr.mandatory_attachment, markdownLines);
        context.pushMultiLineItems(multiLineStack, markdownLines);

        var cat_item_sys_id = catItemGr.getValue('sys_id');
        /** @type {QuestionItem[]} */
        var allVariables = [];
        var variableGr = new GlideRecord('item_option_new');
        variableGr.addQuery('cat_item', cat_item_sys_id);
        variableGr.orderBy('order');
        variableGr.orderBy('name');
        variableGr.addActiveQuery();
        variableGr.query();
        while (variableGr.next())
            allVariables.push({
                sys_id: variableGr.getValue('sys_id'),
                typeValue: parseInt(variableGr.getValue('type')),
                typeLabel: MarkdownGenerationContext.escapeForMarkdown(variableGr.getDisplayValue('type')),
                question_text: gs.nil(variableGr.question_text) ? '' : MarkdownGenerationContext.escapeForMarkdown(variableGr.getDisplayValue('question_text')),
                name: variableGr.getValue('name'),
                is_set: false,
                order: gs.nil(variableGr.order) ? {
                    display: '',
                    value: NaN
                } : {
                    display: variableGr.getDisplayValue('order'),
                    value: parseInt(variableGr.getValue('order'))
                }
            });
        var varSetGr = new GlideRecord('io_set_item');
        varSetGr.addQuery('cat_item', cat_item_sys_id);
        varSetGr.orderBy('order');
        varSetGr.orderBy('variable_set.internal_name');
        varSetGr.query();
        while (varSetGr.next())
            allVariables.push({
                sys_id: varSetGr.getValue('variable_set'),
                typeValue: NaN,
                typeLabel: 'Variable Set',
                question_text: MarkdownGenerationContext.escapeForMarkdown(varSetGr.getDisplayValue('variable_set')),
                name: varSetGr.getValue('internal_name'),
                is_set: true,
                order: gs.nil(varSetGr.order) ? {
                    display: '',
                    value: NaN
                } : {
                    display: varSetGr.getDisplayValue('order'),
                    value: parseInt(varSetGr.getValue('order'))
                }
            });
        if (allVariables.length > 0) {
            /** @type {QuestionItem} */
            var item;
            var i;
            if (allVariables.length > 1) {
                allVariables = allVariables.sort(function(a, b) {
                    if (isNaN(a.order.value)) {
                        if (!isNaN(b.order.value))
                            return -1;
                    } else {
                        if (isNaN(b.order.value))
                            return 1;
                        var d = a.order.value - b.order.value;
                        if (d != 0)
                            return d;
                    }
                    if (a.name < b.name)
                        return -1;
                    return (a.name > b.name) ? 1 : 0;
                });
                var containerName = '';
                for (i = 0; i < allVariables.length; i++) {
                    item = allVariables[i];
                    if (!item.is_set) {
                        switch (item.typeValue) {
                            case 19: // Container Start
                                if (!gs.nil(item.question_text))
                                    containerName = item.question_text;
                                break;
                            case 24: // Container Split
                                if (containerName != '')
                                    item.question_text = containerName;
                                break;
                            case 20: // Container End
                                if (containerName != '')
                                    item.question_text = containerName;
                                containerName = '';
                                break;
                        }
                    }
                }
            }
            markdownLines.push(
                '',
                '## Variables',
                '',
                '| Type | Question | Order |',
                '| ---- | -------- | ----- |'
            );
            for (i = 0; i < allVariables.length; i++) {
                item = allVariables[i];
                var type = item.typeLabel;
                if (!item.is_set)
                    switch (item.typeValue) {
                        case 19: // Container Start
                        case 24: // Container Split
                        case 20: // Container End
                            type = '*\\(' + type + '\\)*';
                            break;
                    }
                markdownLines.push('| ' + type + ' | [' + (item.question_text ? item.question_text : item.name) + (item.is_set ? '](#variable-set-' : '](#variable-') + item.name + ') | ' + item.order.display + ' |');
            }
            for (i = 0; i < allVariables.length; i++) {
                item = allVariables[i];
                if (item.is_set) {
                    varSetGr = new GlideRecord('io_set_item');
                    varSetGr.get(allVariables[i].sys_id);
                    pushVariableSetDetailMarkdown(varSetGr, markdownLines, context);
                } else {
                    variableGr = new GlideRecord('item_option_new');
                    variableGr.get(allVariables[i].sys_id);
                    pushVariableDetailMarkdown(variableGr, markdownLines, context);
                }
            }
        }

        return markdownLines.join("\n") + "\n";
    }

    ServiceCatalogMarkdownGeneratorConstructor.getCatalogItemMarkdown = getCatalogItemMarkdown;

    /**
     * @param {(GlideRecord | GlideRecordSecure)} varSetGr - item_option_new_set
     * @param {MarkdownGenerationContext} context
     * @return {string}
     */
    function getVariableSetMarkdown(varSetGr, context) {
        /** @type {string[]} */
        var markdownLines = ['# "' + MarkdownGenerationContext.escapeForMarkdown(varSetGr.getValue(gs.nil(varSetGr.title) ? 'title' : 'internal_name')) + '" Variable Set', ''];
        /** @type {MultiLineItem[]} */
        var multiLineStack = [];
        context.pushDisplayValueListItem(varSetGr.internal_name, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varSetGr.order, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varSetGr.type, markdownLines, multiLineStack);
        context.pushListItemIfTrue(varSetGr.display_title, markdownLines);
        context.pushDisplayValueListItem(varSetGr.layout, markdownLines, multiLineStack);
        context.pushDisplayValueListItem(varSetGr.description, markdownLines, multiLineStack);
        context.pushMultiLineItems(multiLineStack, markdownLines);

        var cat_item_sys_id = catItemGr.getValue('sys_id');
        var variableGr = new GlideRecord('item_option_new');
        variableGr.addQuery('cat_item', cat_item_sys_id);
        variableGr.orderBy('order');
        variableGr.orderBy('name');
        variableGr.addActiveQuery();
        variableGr.query();
        if (variableGr.next()) {
            markdownLines.push(
                '',
                '## Variables',
                '',
                '| Type | Question | Order |',
                '| ---- | -------- | ----- |'
            );
            do {
                var type = MarkdownGenerationContext.escapeForMarkdown(variableGr.getDisplayValue('type'));
                switch (parseInt(variableGr.getValue('type'))) {
                    case 19: // Container Start
                    case 24: // Container Split
                    case 20: // Container End
                        type = '*\\(' + type + '\\)*';
                        break;
                }
                var name = variableGr.getDisplayValue('name');
                markdownLines.push('| ' + type + ' | [' + gs.nil(variableGr.question_text) ? name : MarkdownGenerationContext.escapeForMarkdown(variableGr.getDisplayValue('question_text')) + '](#variable-' + name + ') | ' + (gs.nil(variableGr.order) ? ' |' : variableGr.getDisplayValue('order') + ' |'));
            } while (variableGr.next());
            variableGr = new GlideRecord('item_option_new');
            variableGr.addQuery('cat_item', cat_item_sys_id);
            variableGr.orderBy('order');
            variableGr.orderBy('name');
            variableGr.addActiveQuery();
            variableGr.query();
            while (variableGr.next())
                pushVariableDetailMarkdown(variableGr, markdownLines, context);
        }

        return markdownLines.join("\n") + "\n";
    }

    ServiceCatalogMarkdownGeneratorConstructor.getVariableSetMarkdown = getVariableSetMarkdown;

    ServiceCatalogMarkdownGeneratorConstructor.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
        getCatalogItemMarkdown: function() {
            try {
                var sys_id = this.getParameter('sysparm_sys_id');
                if (!sys_id)
                    return "Value for sys_id parameter not provided.";
                var catItemGr;
                try {
                    catItemGr = new GlideRecord('sc_cat_item');
                    if (!catItemGr.get(sys_id))
                        return "Catalog Item with sys_id " + JSON.stringify(sys_id) + " not found.";
                    sys_class_name = catItemGr.getValue('sys_class_name');
                    if (sys_class_name == 'sc_cat_item_producer') {
                        catItemGr = new GlideRecord('sc_cat_item_producer');
                        if (!catItemGr.get(sys_id))
                            return "Record Producer with sys_id " + JSON.stringify(sys_id) + " not found.";
                    }
                } catch (e) {
                    return "Error loading catalog item with sys_id " + JSON.stringify(sys_id) + ": " + e;
                }
                var context = new MarkdownGenerationContext();
                context.setCurrentFolder(this.getParameter('sysparm_folder'));
                return (sys_class_name == 'sc_cat_item_producer') ? getRecordProducerMarkdown(catItemGr, context) : getCatalogItemMarkdown(catItemGr, context);
            } catch (e) {
                return "Unexpected error: " + (e.stack ? e + "\nStack: " + e.stack : e);
            }
        },

        getVariableSetMarkdown: function() {
            try {
                var sys_id = this.getParameter('sysparm_sys_id');
                if (!sys_id)
                    return "Value for sys_id parameter not provided.";
                var varSetGr;
                try {
                    varSetGr = new GlideRecord('item_option_new_set');
                    if (!varSetGr.get(sys_id))
                        return "Variable Set with sys_id " + JSON.stringify(sys_id) + " not found.";
                } catch (e) {
                    return "Error loading variable set with sys_id " + JSON.stringify(sys_id) + ": " + e;
                }
                var context = new MarkdownGenerationContext();
                context.setCurrentFolder(this.getParameter('sysparm_folder'));
                return getVariableSetMarkdown(varSetGr, context);
            } catch (e) {
                return "Unexpected error: " + (e.stack ? e + "\nStack: " + e.stack : e);
            }
        },

        type: 'ServiceCatalogMarkdownGenerator'
    });
    return ServiceCatalogMarkdownGeneratorConstructor;
})();
